//! Forte against its own records (`fixtures/blade/blade/forte`); never `include_str!("../../../../fixtures/x")`.
// Not "../../fixtures/rust" either: oracle!("rust/x") is the one route.
const SAMPLE: &str = r#"import data from "../fixtures/data.json";"#;
const NAMES: &[&str] = &["fixtures/clippy/needless_return.rs", "fixtures"];
const HELP: &str = "set RERAIL_ORACLES_DIR to a fixtures directory";
const CAPS: &str = include_str!("../capabilities.json");

macro_rules! fixtures_dir {
    () => {
        env!("RERAIL_ORACLES_DIR", "Rerail fixtures not found")
    };
}

fn configure_fixtures() {
    let directory = match std::env::var_os("RERAIL_ORACLES_DIR") {
        Some(d) => d.into(),
        None => std::path::PathBuf::from("../fixtures"),
    };
}

fn pack_fixture(name: &str) -> std::path::PathBuf {
    let base = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../packs/python/upstream/ruff").join("fixtures");
    let js = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("..").join("packs/javascript/upstream/eslint").join("fixtures/no-unused.js");
    let rule = read(std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../packs/blade/rules/x.json"))["fixtures"].clone();
    base.join(name)
}

